      WHEN 21 THEN (CASE WHEN (cpu.p) & 8 THEN (((0) << 16) | (((((cpu.p) & 0x3C) | (CASE WHEN ((cpu.a) - (val) + (((cpu.p) & 1)) - 1) >= 0 THEN 1 ELSE 0 END) | (CASE WHEN ((((cpu.a) - (val) + (((cpu.p) & 1)) - 1) & 0xFF)) = 0 THEN 2 ELSE 0 END) | ((((cpu.a) - (val) + (((cpu.p) & 1)) - 1)) & 0x80) | (CASE WHEN (((cpu.a) | (val)) & ~((cpu.a) & (val))) & (((cpu.a) | (((cpu.a) - (val) + (((cpu.p) & 1)) - 1))) & ~((cpu.a) & (((cpu.a) - (val) + (((cpu.p) & 1)) - 1)))) & 0x80 THEN 0x40 ELSE 0 END))) << 8) | ((((CASE WHEN (((cpu.a) & 0xF0) - ((val) & 0xF0) + (CASE WHEN (((cpu.a) & 0x0F) - ((val) & 0x0F) + (((cpu.p) & 1)) - 1) < 0 THEN ((((((cpu.a) & 0x0F) - ((val) & 0x0F) + (((cpu.p) & 1)) - 1) - 0x06) & 0x0F) - 0x10) ELSE (((cpu.a) & 0x0F) - ((val) & 0x0F) + (((cpu.p) & 1)) - 1) END)) < 0 THEN ((((cpu.a) & 0xF0) - ((val) & 0xF0) + (CASE WHEN (((cpu.a) & 0x0F) - ((val) & 0x0F) + (((cpu.p) & 1)) - 1) < 0 THEN ((((((cpu.a) & 0x0F) - ((val) & 0x0F) + (((cpu.p) & 1)) - 1) - 0x06) & 0x0F) - 0x10) ELSE (((cpu.a) & 0x0F) - ((val) & 0x0F) + (((cpu.p) & 1)) - 1) END)) - 0x60) ELSE (((cpu.a) & 0xF0) - ((val) & 0xF0) + (CASE WHEN (((cpu.a) & 0x0F) - ((val) & 0x0F) + (((cpu.p) & 1)) - 1) < 0 THEN ((((((cpu.a) & 0x0F) - ((val) & 0x0F) + (((cpu.p) & 1)) - 1) - 0x06) & 0x0F) - 0x10) ELSE (((cpu.a) & 0x0F) - ((val) & 0x0F) + (((cpu.p) & 1)) - 1) END)) END) & 0xFF)) & 0xFF)) ELSE (((0) << 16) | (((((cpu.p) & 0x3C) | (CASE WHEN ((cpu.a) - (val) + (((cpu.p) & 1)) - 1) >= 0 THEN 1 ELSE 0 END) | (CASE WHEN ((((cpu.a) - (val) + (((cpu.p) & 1)) - 1) & 0xFF)) = 0 THEN 2 ELSE 0 END) | ((((cpu.a) - (val) + (((cpu.p) & 1)) - 1)) & 0x80) | (CASE WHEN (((cpu.a) | (val)) & ~((cpu.a) & (val))) & (((cpu.a) | (((cpu.a) - (val) + (((cpu.p) & 1)) - 1))) & ~((cpu.a) & (((cpu.a) - (val) + (((cpu.p) & 1)) - 1)))) & 0x80 THEN 0x40 ELSE 0 END))) << 8) | (((((cpu.a) - (val) + (((cpu.p) & 1)) - 1) & 0xFF)) & 0xFF)) END)  -- SBC
