      WHEN 25 THEN (((0) << 16) | (((((cpu.p) & 0x7D) | (CASE WHEN ((((cpu.a) | (val)) & ~((cpu.a) & (val)))) = 0 THEN 2 ELSE 0 END) | (((((cpu.a) | (val)) & ~((cpu.a) & (val)))) & 0x80))) << 8) | (((((cpu.a) | (val)) & ~((cpu.a) & (val)))) & 0xFF))  -- EOR
