          st1.v AS s1, st2.v AS s2, st3.v AS s3
        FROM memory m0
          JOIN decode d ON d.op = m0.v
          JOIN watch w ON w.id = 1
          JOIN memory m1 ON m1.addr = ((cpu.pc + 1) & 0xFFFF)
          JOIN memory m2 ON m2.addr = ((cpu.pc + 2) & 0xFFFF)
          LEFT JOIN memory pl ON pl.addr = CASE d.mode
      WHEN 10 THEN m1.v  -- (zp),y
      WHEN 9 THEN ((m1.v + cpu.x) & 0xFF)  -- (zp,x)
      WHEN 12 THEN (m1.v | (m2.v << 8))  -- JMP (ind)
      WHEN 13 THEN 0xFFFE  -- BRK vector
    END
          LEFT JOIN memory ph ON ph.addr = CASE d.mode
      WHEN 10 THEN ((m1.v + 1) & 0xFF)  -- (zp),y wraps in page zero
      WHEN 9 THEN ((m1.v + cpu.x + 1) & 0xFF)  -- (zp,x) wraps in page zero
      WHEN 12 THEN (((m1.v | (m2.v << 8)) & 0xFF00) | ((m1.v + 1) & 0xFF))  -- JMP (ind) never crosses a page
      WHEN 13 THEN 0xFFFF  -- BRK vector
    END
          LEFT JOIN memory mv ON mv.addr = CASE WHEN d.reads THEN CASE d.mode
      WHEN 3 THEN m1.v  -- zp
      WHEN 6 THEN (m1.v | (m2.v << 8))  -- abs
      WHEN 4 THEN ((m1.v + cpu.x) & 0xFF)  -- zp,x
      WHEN 7 THEN (((m1.v | (m2.v << 8)) + cpu.x) & 0xFFFF)  -- abs,x
      WHEN 8 THEN (((m1.v | (m2.v << 8)) + cpu.y) & 0xFFFF)  -- abs,y
      WHEN 10 THEN (((pl.v | (ph.v << 8)) + cpu.y) & 0xFFFF)  -- (zp),y
      WHEN 9 THEN (pl.v | (ph.v << 8))  -- (zp,x)
      WHEN 11 THEN ((cpu.pc + 2 + ((m1.v & 0x7F) - (m1.v & 0x80))) & 0xFFFF)  -- branch target
      WHEN 5 THEN ((m1.v + cpu.y) & 0xFF)  -- zp,y
      WHEN 12 THEN (pl.v | (ph.v << 8))  -- JMP (ind)
      WHEN 13 THEN (pl.v | (ph.v << 8))  -- the BRK vector
    END END
          LEFT JOIN memory st1 ON st1.addr = CASE WHEN d.sp >= 1 THEN 0x100 + ((cpu.s + 1) & 0xFF) END
          LEFT JOIN memory st2 ON st2.addr = CASE WHEN d.sp >= 2 THEN 0x100 + ((cpu.s + 2) & 0xFF) END
          LEFT JOIN memory st3 ON st3.addr = CASE WHEN d.sp >= 3 THEN 0x100 + ((cpu.s + 3) & 0xFF) END
        WHERE m0.addr = cpu.pc
      ) g
    ) f
  ) WHERE halted = 0 AND hit IS NULL;
  UPDATE OR FAIL memory SET v = (SELECT w0v FROM cpu) WHERE addr = (SELECT w0a FROM cpu);
  UPDATE OR FAIL memory SET v = (SELECT w1v FROM cpu) WHERE addr = (SELECT w1a FROM cpu);
  UPDATE OR FAIL memory SET v = (SELECT w2v FROM cpu) WHERE addr = (SELECT w2a FROM cpu);
  -- applied: clear the slots, so ticks that find the latch halted or tripped do nothing
  UPDATE OR FAIL cpu SET w0a = NULL, w0v = NULL, w1a = NULL, w1v = NULL, w2a = NULL, w2v = NULL WHERE w0a IS NOT NULL;
  SELECT RAISE(IGNORE);   -- the clock is a signal, not a record
END;

-- The console: llvm-mos sim's two ports, as triggers on memory.
CREATE TABLE console (n INTEGER PRIMARY KEY, ch INTEGER NOT NULL);
CREATE TRIGGER putchar AFTER UPDATE OF v ON memory WHEN NEW.addr = 65529
BEGIN
END;
CREATE TRIGGER exit AFTER UPDATE OF v ON memory WHEN NEW.addr = 65528
BEGIN
  UPDATE cpu SET halted = 1;
END;

