INSERT OR REPLACE INTO memory (addr, v) VALUES (65530,0),(65531,0),(65532,14),(65533,2),(65534,0),(65535,0);

-- Reset: start where the reset vector points.
UPDATE cpu SET pc = (SELECT v FROM memory WHERE addr = 65532) | ((SELECT v FROM memory WHERE addr = 65533) << 8);

-- Run: 222 batches of up to 65,536 clock ticks; once halted, a batch is empty.
BEGIN;
COMMIT;

SELECT rtrim(group_concat(char(ch), ''), char(10)) FROM (SELECT ch FROM console ORDER BY n);
SELECT CASE WHEN halted THEN 'Ran ' || steps || ' 6502 instructions, exit code ' || (SELECT v FROM memory WHERE addr = 65528) || '.' ELSE 'Still running after ' || steps || ' instructions.' END FROM cpu;
